import math

def _build_agent_internal(sandbox, torque=1000.0, arm_config=None, initial_angle=0.5,
                          beam_density=20.0, scoop_density=20.0, tower_density=100.0,
                          bucket_torque=None):
    if bucket_torque is None:
        bucket_torque = torque

    # Add the anchored base at the required position
    sandbox.add_anchored_base(-2.0, 0.2, 0.4, 0.4, angle=0, density=10.0)

    # Add a smaller, lighter tower to reduce mass
    tower = sandbox.add_anchored_base(-2.0, 1.0, 0.4, 0.5, angle=0, density=tower_density)

    if arm_config is None:
        arm_config = [1.5, 1.5, 1.5]  # Three segments for sufficient reach

    prev_body = tower
    prev_anchor = (-2.0, 1.5)  # Starting point on the tower
    current_x, current_y = -2.0, 1.5

    arm_joint = None

    for i, length in enumerate(arm_config):
        center_x = current_x + (length / 2.0) * math.cos(initial_angle)
        center_y = current_y + (length / 2.0) * math.sin(initial_angle)
        body = sandbox.add_beam(center_x, center_y, length, 0.2, angle=initial_angle, density=beam_density)
        if i == 0:
            arm_joint = sandbox.add_revolute_joint(
                prev_body, body, prev_anchor,
                enable_motor=True, max_motor_torque=torque
            )
        else:
            sandbox.add_joint(prev_body, body, (current_x, current_y))
        prev_body = body
        current_x += length * math.cos(initial_angle)
        current_y += length * math.sin(initial_angle)

    # Scoop with size to hold up to 6 particles
    scoop_w, scoop_h = 1.5, 0.7
    scoop = sandbox.add_scoop(current_x, current_y, scoop_w, scoop_h, angle=initial_angle, density=scoop_density)

    bucket_joint = sandbox.add_revolute_joint(
        prev_body, scoop, (current_x, current_y),
        enable_motor=True, max_motor_torque=bucket_torque
    )

    return {
        "body": scoop,
        "arm_joint": arm_joint,
        "bucket_joint": bucket_joint,
    }


def _control_components(agent_components):
    if not isinstance(agent_components, dict):
        return None, None, None
    return (
        agent_components.get("body"),
        agent_components.get("arm_joint"),
        agent_components.get("bucket_joint"),
    )


def build_agent(sandbox):
    return _build_agent_internal(sandbox, torque=1000.0, initial_angle=0.5)


def agent_action(sandbox, agent_body, step_count):
    scoop, aj, bj = _control_components(agent_body)
    if scoop is None or not aj or not bj:
        return

    dt = 1.0 / 60.0
    t = step_count * dt
    phase_duration = 4.0  # Total cycle time
    phase = (t % phase_duration) / phase_duration

    # Define target angles based on phase
    if phase < 0.2:
        ta, tb = 0.5, -1.0  # Scoop down to grab material
    elif phase < 0.4:
        ta, tb = 0.5, -1.0  # Hold position to scoop
    elif phase < 0.6:
        ta, tb = 1.5, 0.0  # Lift arm and close bucket
    elif phase < 0.8:
        ta, tb = 2.356, -1.0  # Move to hopper position and dump
    else:
        ta, tb = 0.5, -1.0  # Return to start position

    # Proportional control with adjusted gains
    aj.motorSpeed = 1.2 * (ta - aj.angle)
    bj.motorSpeed = 2.5 * (tb - scoop.angle)
    aj.motorEnabled = True
    bj.motorEnabled = True
